package com.javatpoint.servlets;
import java.io.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import com.javatpoint.beans.LibrarianBean;import com.javatpoint.dao.LibrarianDao;import com.javatpoint.util.*;
@WebServlet("/EditLibrarianForm") public class EditLibrarianForm extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{if(!AuthUtil.requireAdmin(q,r))return;try{int id=Integer.parseInt(q.getParameter("id"));LibrarianBean b=LibrarianDao.viewById(id);r.setContentType("text/html;charset=UTF-8");PrintWriter o=r.getWriter();o.print("<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Edit librarian | eLibrary</title><link rel='stylesheet' href='bootstrap.min.css'><link rel='stylesheet' href='app.css'></head><body>");q.getRequestDispatcher("navadmin.html").include(q,r);o.print("<div class='page'><div class='card form-card'><h2>Edit librarian</h2><form action='EditLibrarian' method='post'><input type='hidden' name='id' value='"+b.getId()+"'><div class='form-group'><label>Name</label><input class='form-control' name='name' value='"+HtmlUtil.e(b.getName())+"' required></div><div class='form-group'><label>Email</label><input class='form-control' type='email' name='email' value='"+HtmlUtil.e(b.getEmail())+"' required></div><div class='form-group'><label>New password <span class='muted'>(leave blank to keep current)</span></label><input class='form-control' type='password' name='password' autocomplete='new-password'></div><div class='form-group'><label>Mobile</label><input class='form-control' type='tel' name='mobile' value='"+b.getMobile()+"' pattern='[0-9]{10}' required></div><button class='btn btn-primary'>Save changes</button></form></div></div></body></html>");}catch(NumberFormatException e){r.sendError(400,"Invalid librarian ID.");}}}
